import * as React from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import {
  Box,
  CircularProgress,
  useMediaQuery,
} from '@mui/material';
import { useTranslation } from 'react-i18next';
import { theme } from '../../../../theme';
import { useDeleteTreatmentsMutation } from '../../../posApi';
import { useNotifier } from '../../../../core/Notifier';
import { appColors } from '../../../../theme/appColors';
import { useFormik } from 'formik';
import { ITreatments } from '../../../../core/Interface/treatment.interface';

interface INewTreatments {
  openModel?: boolean;
  title: string;
  handleCloseDialog: (close: boolean) => void;
  data?: ITreatments;
}

const DeleteTreatments = ({
  title,
  openModel = true,
  handleCloseDialog,
  data,
}: INewTreatments) => {
  const { t } = useTranslation(['common', 'product', 'category']);
  const [open] = React.useState(openModel);
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [deleteTreatments, { isLoading }] = useDeleteTreatmentsMutation();
  const { showErrorMessage, showMessage } = useNotifier();

  const handleClose = () => {
    handleCloseDialog(false);
  };

  const formik = useFormik({
    initialValues: {
      id: data?.id
    },
    onSubmit: async (values) => {
      try {
        const response = await deleteTreatments(data?.id|| '').unwrap();
        if (!response.status) {
          showErrorMessage(response.message);
        } else {
          showMessage(response.message);
          handleClose();
        }
      } catch (error) {
        showErrorMessage((error as Error).message);
      }
    },
  });

  const buttonText = data ? t('common:delete') : t('common:create');

  return (
    <div>
      <form onSubmit={formik.handleSubmit}>
        <Dialog
          aria-describedby="alert-dialog-description"
          classes={{ paper: 'inherit' }}
          fullScreen={isMobile}
          fullWidth={isMobile}
          maxWidth="lg"
          open={open}
        >
          <DialogTitle
            sx={{
              fontWeight: 600,
              p: 3,
              backgroundColor: appColors.blueGreyishLight[30],
              borderRadius: '5px',
            }}
          >
            {title}
          </DialogTitle>
          <DialogContent
            sx={{ width: isMobile ? 'auto' : '40vw', p: 4, marginTop: '20px' }}
          >
            <Box>
              Do you want to delete <strong>{data?.dissese}</strong>
            </Box>
          </DialogContent>
          <DialogActions sx={{ paddingRight: '24px', p: 4, py: 3, gap: 2 }}>
            <Button
              onClick={() => {
                handleClose();
              }}
              sx={{ width: 200, height: 42, borderRadius: '5px' }}
              variant="outlined"
            >
              {t('common:cancel')}
            </Button>
            <Button
              autoFocus
              onClick={() => {
                formik.handleSubmit();
              }}
              sx={{ width: 200, height: 42, borderRadius: '5px' }}
              type="submit"
              variant="contained"
            >
              {isLoading && (
                <Box sx={{ pr: 2, pt: 0.5 }}>
                  <CircularProgress
                    size={16}
                    sx={{ color: 'white' }}
                  />
                </Box>
              )}
              {buttonText}
            </Button>
          </DialogActions>
        </Dialog>
      </form>
    </div>
  );
};

export default React.memo(DeleteTreatments);