import React, { useMemo, useState } from 'react';

import {
  Box,
  Button,
  CircularProgress,
  Grid,
  InputAdornment,
  MenuItem,
  Select,
  SelectChangeEvent,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import useUser from '../../../../core/hooks/useUser';
import { useTranslation } from 'react-i18next';
import { useFormik } from 'formik';
import { useNotifier } from '../../../../core/Notifier';
import SearchIcon from '@mui/icons-material/Search';
import PatientBasicCard from './PatientBasicCard';
import AddIcon from '@mui/icons-material/Add';
import NewPatient from './NewPatient';
import {
  useGetPatientByIdQuery,
  useRegisterTreatmentMutation,
  useGetReferenceDataQuery,
} from '../../../posApi';
import PatientHistory from './PatientHistory';
import { Privileges } from '../../../../core/types/commonType';
import { IPatientCard } from '../../../../core/Interface/patient.interface';
import {
  IDentalTreatmentType,
  ReferenceData,
} from '../../../../core/Interface/treatment.interface';

const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';
const MID  = '#1E3A8A';

const fieldSx = {
  '& .MuiOutlinedInput-root': {
    backgroundColor: alpha(TEAL, 0.03),
    borderRadius: '8px',
    '& fieldset': { borderColor: alpha(TEAL, 0.2) },
    '&.Mui-focused fieldset': { borderColor: TEAL },
    '&:hover fieldset': { borderColor: alpha(TEAL, 0.4) },
  },
};

const selectSx = {
  backgroundColor: alpha(TEAL, 0.03),
  borderRadius: '8px',
  width: '100%',
  '& .MuiOutlinedInput-notchedOutline': {
    borderColor: alpha(TEAL, 0.2),
  },
  '&:hover .MuiOutlinedInput-notchedOutline': {
    borderColor: alpha(TEAL, 0.4),
  },
  '&.Mui-focused .MuiOutlinedInput-notchedOutline': {
    borderColor: TEAL,
  },
};

const QUADRANTS: { label: string; teeth: number[]; border: string }[] = [
  {
    label: 'Upper Right',
    teeth: [1, 2, 3, 4, 5, 6, 7, 8],
    border: 'borderBottom borderRight',
  },
  {
    label: 'Upper Left',
    teeth: [9, 10, 11, 12, 13, 14, 15, 16],
    border: 'borderBottom borderLeft',
  },
  {
    label: 'Lower Right',
    teeth: [17, 18, 19, 20, 21, 22, 23, 24],
    border: 'borderTop borderRight',
  },
  {
    label: 'Lower Left',
    teeth: [25, 26, 27, 28, 29, 30, 31, 32],
    border: 'borderTop borderLeft',
  },
];

const TreatmentsView = () => {
  const { t } = useTranslation(['common']);
  const { userHasRight } = useUser();
  const { showErrorMessage, showMessage } = useNotifier();
  const [open, setOpen] = useState(false);
  const [selectedTeeth, setSelectedTeeth] = useState<string[]>([]);
  const [patientNumber, setPatientNumber] = useState<string>('');
  const [registerTreatment] = useRegisterTreatmentMutation();
  const { data, isFetching } = useGetPatientByIdQuery(
    patientNumber.split('_')[0],
    { skip: !patientNumber }
  );
  const { data: refData } = useGetReferenceDataQuery();

  const patient = useMemo(() => {
    if (!data?.data) {
      return { message: data?.message } as IPatientCard;
    }
    const d = data?.data as IPatientCard;
    return { message: data?.message, ...d } as IPatientCard;
  }, [data]);

  const formik = useFormik({
    initialValues: {
      patientId: '',
      dissese: '',
      amount: '',
      medition: '',
      tretmentType: '',
      treatedTeeth: '',
    },
    onSubmit: async (values) => {
      try {
        const response = await registerTreatment({
          ...values,
          patientId: patient.id,
        }).unwrap();
        if (!response.status) {
          showErrorMessage(response.message);
        } else {
          showMessage(response.message);
          formik.resetForm();
          setSelectedTeeth([]);
        }
      } catch (error) {
        showErrorMessage((error as Error).message);
      }
    },
  });

  const formikNew = useFormik({
    initialValues: { patientId: '' },
    onSubmit: async (values) => {
      try {
        setPatientNumber(values.patientId);
      } catch (error) {
        showErrorMessage('Please check you data');
      }
    },
  });

  const handleCheckboxSelect = (value: string) => {
    const index = selectedTeeth.indexOf(value);
    const updatedTeeth =
      index === -1
        ? [...selectedTeeth, value]
        : selectedTeeth.filter((item) => item !== value);
    formik.setFieldValue('treatedTeeth', updatedTeeth.join(', '));
    setSelectedTeeth(updatedTeeth);
  };

  const handleChange = (event: SelectChangeEvent) => {
    formik.setFieldValue('tretmentType', event.target.value);
  };

  const dentalTreatmentTypes = useMemo<IDentalTreatmentType[]>(() => {
    return (refData?.data as ReferenceData)?.dentalTreatmentTypes || [];
  }, [refData]);

  return (
    <Box>
      {/* ── Search / action bar ───────────────────────────────── */}
      <Box
        sx={{
          alignItems: 'center',
          background: '#fff',
          border: `1px solid ${alpha(TEAL, 0.15)}`,
          borderRadius: '12px',
          display: 'flex',
          flexWrap: 'wrap',
          gap: 1.5,
          justifyContent: 'space-between',
          mb: 2,
          p: 2,
        }}
      >
        <form
          onSubmit={formikNew.handleSubmit}
          style={{ alignItems: 'center', display: 'flex', gap: 8 }}
        >
          <TextField
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon
                    sx={{ color: alpha(NAVY, 0.35), fontSize: 18 }}
                  />
                </InputAdornment>
              ),
            }}
            autoComplete="off"
            name="patientId"
            onChange={formikNew.handleChange}
            placeholder="Patient Number"
            size="small"
            sx={{ ...fieldSx, width: 280 }}
            value={formikNew.values.patientId}
            variant="outlined"
          />
          <Button
            disabled={isFetching}
            startIcon={
              isFetching ? (
                <CircularProgress
                  size={14}
                  sx={{ color: '#fff' }}
                />
              ) : undefined
            }
            sx={{
              background: `linear-gradient(135deg, ${TEAL} 0%, ${MID} 100%)`,
              borderRadius: '8px',
              boxShadow: `0 4px 12px ${alpha(TEAL, 0.35)}`,
              color: '#fff',
              fontWeight: 700,
              height: 40,
              minWidth: 100,
              '&:hover': {
                background:
                  `linear-gradient(135deg, ${MID} 0%, ${NAVY} 100%)`,
              },
              '&.Mui-disabled': {
                background: alpha(TEAL, 0.35),
                color: alpha('#fff', 0.7),
              },
            }}
            type="submit"
            variant="contained"
          >
            {t('common:search')}
          </Button>
        </form>

        {userHasRight(Privileges.PatientAdd) && (
          <Button
            onClick={() => setOpen(true)}
            startIcon={<AddIcon />}
            sx={{
              background:
                `linear-gradient(135deg, ${NAVY} 0%, ${MID} 100%)`,
              borderRadius: '8px',
              boxShadow: `0 4px 12px ${alpha(NAVY, 0.3)}`,
              color: '#fff',
              fontWeight: 700,
              height: 40,
              '&:hover': {
                background:
                  `linear-gradient(135deg, ${MID} 0%, ${TEAL} 100%)`,
              },
            }}
            variant="contained"
          >
            {t('common:create')} Patient
          </Button>
        )}
      </Box>

      {/* ── Main content ─────────────────────────────────────── */}
      <Grid
        container
        justifyContent="space-around"
        spacing={2}
      >
        <PatientBasicCard
          address={patient?.address || ''}
          age={patient?.age}
          dateOfBirth={patient?.dateOfBirth}
          id={patient?.id}
          message={patient?.message}
          mobile={patient?.mobile}
          name={patient?.name}
          patientNumber={patient?.patientNumber}
        />

        <Grid
          item
          lg={8}
          sm={12}
          xs={12}
        >
          <Box
            sx={{
              background: '#fff',
              border: `1px solid ${alpha(TEAL, 0.15)}`,
              borderRadius: '12px',
              boxShadow: `0 4px 24px ${alpha(NAVY, 0.05)}`,
              overflow: 'hidden',
            }}
          >
            {/* card accent bar */}
            <Box
              sx={{
                background:
                  `linear-gradient(90deg, ${TEAL} 0%, ${alpha(TEAL, 0.5)} 100%)`,
                height: 3,
              }}
            />

            <form onSubmit={formik.handleSubmit}>
              <Grid
                container
                spacing={2}
                sx={{ p: 2.5 }}
              >
                {/* Treatment type */}
                <GridItem>
                  <FieldLabel>Type of Treatment</FieldLabel>
                  <Select
                    {...formik.getFieldProps('tretmentType')}
                    onChange={handleChange}
                    size="small"
                    sx={selectSx}
                    value={formik.values.tretmentType}
                  >
                    {dentalTreatmentTypes.map(
                      ({ key, value }: IDentalTreatmentType) => (
                        <MenuItem
                          key={key}
                          value={key}
                        >
                          {value}
                        </MenuItem>
                      )
                    )}
                  </Select>
                </GridItem>

                {/* ── Tooth chart ────────────────────────────────── */}
                <GridItem>
                  <FieldLabel>Tooth Chart</FieldLabel>

                  {/* Selected teeth summary */}
                  {selectedTeeth.length > 0 && (
                    <Box
                      sx={{
                        alignItems: 'center',
                        background: alpha(TEAL, 0.06),
                        border: `1px solid ${alpha(TEAL, 0.2)}`,
                        borderRadius: '8px',
                        display: 'flex',
                        flexWrap: 'wrap',
                        gap: 0.5,
                        mb: 1.5,
                        px: 1.5,
                        py: 0.75,
                      }}
                    >
                      <Typography
                        sx={{
                          color: alpha(TEAL, 0.8),
                          fontSize: 10,
                          fontWeight: 700,
                          letterSpacing: '0.5px',
                          mr: 0.5,
                          textTransform: 'uppercase',
                        }}
                      >
                        Selected:
                      </Typography>
                      {selectedTeeth.sort((a, b) => +a - +b).map((tn) => (
                        <Box
                          key={tn}
                          sx={{
                            background: TEAL,
                            borderRadius: '4px',
                            color: '#fff',
                            fontSize: 10,
                            fontWeight: 800,
                            px: 0.75,
                            py: 0.25,
                          }}
                        >
                          {tn}
                        </Box>
                      ))}
                    </Box>
                  )}

                  <Box
                    sx={{
                      background: alpha(TEAL, 0.015),
                      border: `1px solid ${alpha(TEAL, 0.15)}`,
                      borderRadius: '12px',
                      overflow: 'hidden',
                    }}
                  >
                    {/* Legend */}
                    <Box
                      sx={{
                        alignItems: 'center',
                        background: alpha(NAVY, 0.03),
                        borderBottom: `1px solid ${alpha(TEAL, 0.1)}`,
                        display: 'flex',
                        gap: 2,
                        justifyContent: 'center',
                        py: 0.75,
                      }}
                    >
                      <Box
                        sx={{
                          alignItems: 'center',
                          display: 'flex',
                          gap: 0.5,
                        }}
                      >
                        <ToothIcon
                          id="legend-healthy"
                          selected={false}
                          size={14}
                        />
                        <Typography
                          sx={{
                            color: alpha(NAVY, 0.45),
                            fontSize: 10,
                          }}
                        >
                          Healthy
                        </Typography>
                      </Box>
                      <Box
                        sx={{
                          alignItems: 'center',
                          display: 'flex',
                          gap: 0.5,
                        }}
                      >
                        <ToothIcon
                          id="legend-selected"
                          selected
                          size={14}
                        />
                        <Typography
                          sx={{ color: TEAL, fontSize: 10 }}
                        >
                          Selected for treatment
                        </Typography>
                      </Box>
                    </Box>

                    {/* 4 quadrants */}
                    <Grid container>
                      {QUADRANTS.map((q) => {
                        const isRight = q.label.includes('Right');
                        const isUpper = q.label.includes('Upper');
                        return (
                          <Grid
                            item
                            key={q.label}
                            lg={6}
                            sm={6}
                            sx={{
                              borderBottom: isUpper
                                ? `2px solid ${alpha(TEAL, 0.18)}`
                                : undefined,
                              borderLeft: !isRight
                                ? `2px solid ${alpha(TEAL, 0.18)}`
                                : undefined,
                              borderRight: isRight
                                ? `2px solid ${alpha(TEAL, 0.18)}`
                                : undefined,
                              borderTop: !isUpper
                                ? `2px solid ${alpha(TEAL, 0.18)}`
                                : undefined,
                              p: 1.5,
                            }}
                            xs={6}
                          >
                            <Typography
                              sx={{
                                color: TEAL,
                                fontSize: 10,
                                fontWeight: 700,
                                letterSpacing: '0.4px',
                                mb: 1,
                                textTransform: 'uppercase',
                              }}
                            >
                              {q.label}
                            </Typography>
                            <Box
                              sx={{
                                display: 'flex',
                                flexWrap: 'wrap',
                                gap: '4px',
                              }}
                            >
                              {q.teeth.map((v) => (
                                <ToothButton
                                  key={v}
                                  number={v}
                                  onClick={() =>
                                    handleCheckboxSelect(v.toString())
                                  }
                                  selected={selectedTeeth.includes(
                                    v.toString()
                                  )}
                                />
                              ))}
                            </Box>
                          </Grid>
                        );
                      })}
                    </Grid>
                  </Box>
                </GridItem>

                {/* Disease */}
                <GridItem>
                  <FieldLabel>Disease</FieldLabel>
                  <TextField
                    autoComplete="off"
                    fullWidth
                    multiline
                    placeholder="Disease"
                    rows={2}
                    size="small"
                    sx={fieldSx}
                    {...formik.getFieldProps('dissese')}
                  />
                </GridItem>

                {/* Medication */}
                <GridItem>
                  <FieldLabel>Medication</FieldLabel>
                  <TextField
                    autoComplete="off"
                    fullWidth
                    multiline
                    placeholder="Medication"
                    rows={2}
                    size="small"
                    sx={fieldSx}
                    {...formik.getFieldProps('medition')}
                  />
                </GridItem>

                {/* Amount */}
                <GridItem>
                  <FieldLabel>Amount</FieldLabel>
                  <TextField
                    autoComplete="off"
                    fullWidth
                    placeholder="Amount"
                    size="small"
                    sx={fieldSx}
                    type="number"
                    {...formik.getFieldProps('amount')}
                  />
                </GridItem>

                {/* Submit */}
                <GridItem
                  sx={{
                    alignItems: 'flex-end',
                    display: 'flex',
                    flexDirection: 'column',
                    pt: 1,
                  }}
                >
                  <Button
                    disabled={!patient?.patientNumber}
                    sx={{
                      background: patient?.patientNumber
                        ? `linear-gradient(135deg, ${TEAL} 0%, ${MID} 100%)`
                        : undefined,
                      borderRadius: '8px',
                      boxShadow: patient?.patientNumber
                        ? `0 4px 14px ${alpha(TEAL, 0.4)}`
                        : undefined,
                      color: '#fff',
                      fontWeight: 700,
                      height: 42,
                      minWidth: 130,
                      '&:hover': {
                        background:
                          `linear-gradient(135deg, ${MID} 0%, ${NAVY} 100%)`,
                      },
                      '&.Mui-disabled': {
                        background: alpha(NAVY, 0.1),
                        color: alpha(NAVY, 0.35),
                      },
                    }}
                    type="submit"
                    variant="contained"
                  >
                    {t('common:submit')}
                  </Button>
                </GridItem>
              </Grid>
            </form>
          </Box>
        </Grid>
      </Grid>

      <PatientHistory treatements={patient.treatements} />

      {open && (
        <NewPatient
          data={undefined}
          handleCloseDialog={() => setOpen(false)}
          openModel={open}
          title={false ? 'Edit Patient' : 'Create New Patient'}
        />
      )}
    </Box>
  );
};

// eslint-disable-next-line react/no-multi-comp
const GridItem = ({ ...rest }) => (
  <Grid
    item
    lg={12}
    sm={12}
    sx={{ alignItems: 'start', display: 'flex', flexDirection: 'column' }}
    xs={12}
    {...rest}
  />
);

// eslint-disable-next-line react/no-multi-comp
const FieldLabel = ({ children }: { children: React.ReactNode }) => (
  <Typography
    sx={{
      color: alpha(NAVY, 0.5),
      fontSize: 11,
      fontWeight: 700,
      letterSpacing: '0.5px',
      mb: 0.75,
      textTransform: 'uppercase',
    }}
  >
    {children}
  </Typography>
);

// eslint-disable-next-line react/no-multi-comp
const ToothIcon = ({
  id,
  selected,
  size = 22,
}: {
  id: string;
  selected: boolean;
  size?: number;
}) => {
  const cg = `tcg-${id}`;
  const rg = `trg-${id}`;
  const sf = `tsf-${id}`;

  /* ── colour tokens ── */
  const eTop  = selected ? '#B8ECEC' : '#FFFFFF';
  const eMid  = selected ? '#1EA8AA' : '#DCF0F6';
  const eEdge = selected ? '#0A6668' : '#A4C8D8';
  const dTop  = selected ? '#5ECECE' : '#F4EAD8';
  const dBot  = selected ? '#0A6668' : '#C8AA88';
  const str   = selected ? '#0A6668' : '#A8C4D0';
  const sdCol = selected
    ? 'rgba(10,102,104,0.38)'
    : 'rgba(15,29,77,0.18)';

  return (
    <svg
      fill="none"
      height={(size * 36) / 24}
      viewBox="0 0 24 36"
      width={size}
    >
      <defs>
        {/* Crown: radial gradient — bright top-left, dark edge */}
        <radialGradient
          cx="36%"
          cy="22%"
          id={cg}
          r="74%"
        >
          <stop
            offset="0%"
            stopColor={eTop}
          />
          <stop
            offset="46%"
            stopColor={eMid}
          />
          <stop
            offset="100%"
            stopColor={eEdge}
          />
        </radialGradient>

        {/* Roots: linear gradient top→tip */}
        <linearGradient
          id={rg}
          x1="25%"
          x2="75%"
          y1="0%"
          y2="100%"
        >
          <stop
            offset="0%"
            stopColor={dTop}
          />
          <stop
            offset="100%"
            stopColor={dBot}
          />
        </linearGradient>

        {/* Drop-shadow filter */}
        <filter
          height="160%"
          id={sf}
          width="180%"
          x="-40%"
          y="-20%"
        >
          <feDropShadow
            dx="0"
            dy="1.8"
            floodColor={sdCol}
            stdDeviation="1.4"
          />
        </filter>
      </defs>

      {/* ── Roots (rendered behind crown) ── */}
      <path
        d="M8 20 L7 28 Q6.5 33 9 33 Q11.5 33 11 28 L10 20 Z"
        fill={`url(#${rg})`}
        stroke={str}
        strokeLinejoin="round"
        strokeWidth="0.6"
      />
      <path
        d="M14 20 L14 28 Q13.5 33 16 33 Q18.5 33 18 28 L16 20 Z"
        fill={`url(#${rg})`}
        stroke={str}
        strokeLinejoin="round"
        strokeWidth="0.6"
      />

      {/* Ambient-occlusion shadow at gum line */}
      <path
        d="M7 20 Q12 23.5 17 20"
        fill="none"
        opacity="0.25"
        stroke="rgba(0,0,0,0.55)"
        strokeLinecap="round"
        strokeWidth="2"
      />

      {/* ── Crown with drop shadow ── */}
      <path
        d="M4 16 Q4 1 12 1 Q20 1 20 16 Q20 20 16 20 L8 20 Q4 20 4 16 Z"
        fill={`url(#${cg})`}
        filter={`url(#${sf})`}
        stroke={str}
        strokeWidth="0.75"
      />

      {/* Right-edge darkening (form shadow) */}
      <path
        d="M19.5 8 Q19.8 14 18.5 19.5"
        fill="none"
        opacity="0.22"
        stroke="rgba(0,0,0,0.6)"
        strokeLinecap="round"
        strokeWidth="2.5"
      />

      {/* Rim light — left edge */}
      <path
        d="M4.6 14 Q4.9 5.5 9.8 2"
        fill="none"
        opacity="0.6"
        stroke="rgba(255,255,255,0.95)"
        strokeLinecap="round"
        strokeWidth="1.2"
      />

      {/* Primary specular highlight */}
      <ellipse
        cx="8.8"
        cy="7.2"
        fill="rgba(255,255,255,0.78)"
        rx="2"
        ry="3"
      />

      {/* Secondary specular dot */}
      <circle
        cx="14.5"
        cy="4.5"
        fill="rgba(255,255,255,0.42)"
        r="1.1"
      />

      {/* Bottom rim shading */}
      <path
        d="M5 17.8 Q12 19.5 19 17.8"
        fill="none"
        opacity="0.28"
        stroke="rgba(0,0,0,0.35)"
        strokeLinecap="round"
        strokeWidth="0.9"
      />
    </svg>
  );
};

// eslint-disable-next-line react/no-multi-comp
const ToothButton = ({
  number,
  onClick,
  selected,
}: {
  number: number;
  onClick: () => void;
  selected: boolean;
}) => (
  <Box
    onClick={onClick}
    sx={{
      alignItems: 'center',
      borderRadius: '8px',
      cursor: 'pointer',
      display: 'flex',
      flexDirection: 'column',
      gap: '2px',
      p: '4px',
      transition: 'all 0.15s cubic-bezier(0.34,1.56,0.64,1)',
      userSelect: 'none',
      '&:hover': {
        background: selected ? alpha(TEAL, 0.1) : alpha(NAVY, 0.05),
        transform: 'translateY(-3px) scale(1.12)',
      },
      '&:active': { transform: 'translateY(0) scale(0.96)' },
    }}
  >
    <ToothIcon
      id={number.toString()}
      selected={selected}
    />
    <Typography
      sx={{
        color: selected ? TEAL : alpha(NAVY, 0.4),
        fontSize: 9,
        fontWeight: 800,
        lineHeight: 1,
        mt: '1px',
      }}
    >
      {number}
    </Typography>
  </Box>
);

export default TreatmentsView;
